```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

const LAST_INPUT_KEY: &str = "last-input";
const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record the input in the shared store before anything else.
        // This is a side effect only and does not affect the output.
        state_rw::put(LAST_INPUT_KEY, &feed_url);

        // Read the time.
        let seconds = wall_clock::now().seconds;

        // Make the one permitted fetch. A transport failure counts as zero
        // characters fetched. A host outside the allowlist traps at the
        // boundary, as the capability intends.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notify the digest channel. The contract requires `notified == true`,
        // so retry a bounded number of times. If the notification is still
        // refused, trap instead of producing an output that violates the
        // contract.
        let message = format!(
            "heartbeat: t={} fetched={} chars from {}",
            seconds, fetched, feed_url
        );
        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }
        if !notified {
            panic!("notifier refused heartbeat; cannot satisfy `notified == true`");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
